from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 lines=f.read_text().splitlines(); page='?'; out=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'perpet|indefinit|(?:"'^|'"\\s)(?:\\d+\\.?\\s*)?(?:TERM AND TERMINATION|TERM OF AGREEMENT|DURATION)|(?:shall|will) (?:continue|remain) (?:in|effective)|(?:\\d+\\.?\\s+)Term[.:]',l,re.I):
   out.append('p.'+page+' '+' '.join(lines[i:i+4]))
 print(f.name[:-4]); print('\\n'.join(out) if out else 'NO TARGET PHRASE')
